package tui

import (
	"encoding/json"
	"os"
	"testing"
)

func TestParseColorUsesJavaScriptWhitespaceInOklch(t *testing.T) {
	withoutUnicodeSpace, err := ParseColor("oklch(0.6 0.1 180)")
	if err != nil {
		t.Fatal(err)
	}
	withUnicodeSpace, err := ParseColor("oklch(\u00a00.6\u00a00.1\u00a0180\u00a0)")
	if err != nil {
		t.Fatalf("ParseColor with non-breaking spaces: %v", err)
	}
	if got, want := ColorToRgb(withUnicodeSpace), ColorToRgb(withoutUnicodeSpace); got != want {
		t.Fatalf("unicode-space color = %+v, want %+v", got, want)
	}
}

// Golden generated by driving upstream packages/tui/src/colors.ts (bf8e4b953)
// with Node: OklchToRgb over a lightness/chroma/hue grid and ParseColor over
// hex, oklch() and okhsl() values.
type oklchGoldenFile struct {
	Oklch []struct {
		L   float64  `json:"l"`
		C   float64  `json:"c"`
		H   float64  `json:"h"`
		RGB RgbColor `json:"rgb"`
	} `json:"oklch"`
	Parse []struct {
		Value string   `json:"value"`
		RGB   RgbColor `json:"rgb"`
	} `json:"parse"`
}

func TestOklchAgainstUpstreamGolden(t *testing.T) {
	data, err := os.ReadFile("testdata/oklch_golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden oklchGoldenFile
	if err := json.Unmarshal(data, &golden); err != nil {
		t.Fatal(err)
	}
	for _, c := range golden.Oklch {
		if got := OklchToRgb(c.L, c.C, c.H); got != c.RGB {
			t.Fatalf("OklchToRgb(%v, %v, %v) = %+v (want %+v)", c.L, c.C, c.H, got, c.RGB)
		}
	}
	for _, c := range golden.Parse {
		got, err := ParseColor(c.Value)
		if err != nil {
			t.Fatalf("ParseColor(%q): %v", c.Value, err)
		}
		if rgb := ColorToRgb(got); rgb != c.RGB {
			t.Fatalf("ParseColor(%q) = %+v (want %+v)", c.Value, rgb, c.RGB)
		}
	}
	if _, err := ParseColor("someVariable"); err == nil {
		t.Fatal("a variable reference parsed as a color")
	}
}
